const byID=new Map(BURST_CATALOG.spells.map(s=>[s.id,s]));
export const burstSpell=id=>byID.get(Number(id));
export function burstSpellsForSpec(specID){return BURST_CATALOG.spells.filter(s=>s.specs.includes(Number(specID))).sort((a,b)=>Number(b.primarySpecs.includes(Number(specID)))-Number(a.primarySpecs.includes(Number(specID)))||a.name.localeCompare(b.name,"zh-CN"));}
export const spellNames=Object.fromEntries(BURST_CATALOG.spells.map(s=>[s.id,s.name]));
